from rest_framework.response import Response


def error_response(code, message, status, request):
    body = {"error": {"code": code, "message": message, "request_id": request.id}}
    return Response(body, status=status)


def list_tasks(request, project_id):
    qs = Task.objects.for_tenant(request.workspace).filter(project_id=project_id)
    page = paginate_cursor(qs, request.GET.get("cursor"), order=("-updated_at", "id"))
    return Response(TaskListSerializer(page, many=True).data)


def create_task(request, project_id):
    key = request.headers.get("Idempotency-Key")
    if key and (cached := replay(key)):
        return cached
    return Response(save_task(request, project_id), status=201)

