import hashlib
import hmac
import random

from app.settings import base as settings


def sign_payload(secret, timestamp, body):
    msg = f"{timestamp}.".encode() + body
    return hmac.new(secret.encode(), msg, hashlib.sha256).hexdigest()


def next_delay(attempt):
    cap = min(60 * 60 * 6, 30 * 2 ** attempt)
    return random.uniform(0, cap)


def deliver(endpoint, event, attempt=1):
    resp = post(endpoint.url, event.body, timeout=5)
    if resp.ok:
        return
    if attempt >= settings.WEBHOOK_MAX_ATTEMPTS or resp.status == 410:
        endpoint.disable("too many failures")
        return
    enqueue("webhooks", deliver, endpoint.id, event.id, attempt + 1, delay=next_delay(attempt))

