def handle_event(event):
    if already_processed(event.id):
        return
    if event.type == "customer.subscription.updated":
        apply_subscription(event.data)
    elif event.type == "invoice.payment_failed":
        start_dunning(event.data)
    mark_processed(event.id)


def apply_subscription(data):
    sub = SubscriptionState.objects.get(provider_id=data["id"])
    sub.seats = data["quantity"]
    sub.plan = data["plan"]
    sub.save()


def start_dunning(data):
    schedule_retries(data["customer"], attempts=3, every_days=3)

