import csv

from app.settings import base as settings


def escape_cell(value):
    text = str(value)
    if text[:1] in ("=", "+", "-", "@"):
        return "'" + text
    return text


def export_tasks_csv(workspace, out):
    writer = csv.writer(out)
    out.write("\ufeff")
    qs = Task.all_objects.filter(project__workspace=workspace)[: settings.EXPORT_ROW_LIMIT]
    for chunk in chunked(qs.iterator(chunk_size=2000), 2000):
        writer.writerows([[escape_cell(c) for c in row_values(t)] for t in chunk])

