def index_task(task_id):
    task = Task.all_objects.get(id=task_id)
    if task.deleted_at:
        return remove_task(task_id)
    SearchDoc.objects.update_or_create(
        task_id=task_id, defaults={"tsv": to_tsvector("english", task.title + " " + task.description)})


def remove_task(task_id):
    SearchDoc.objects.filter(task_id=task_id).delete()


def search_tasks(workspace, query, limit=50):
    q = SearchQuery(query, config="english")
    return SearchDoc.objects.filter(workspace=workspace, tsv=q).order_by("-rank")[:limit]

