def parse_due(raw):
    if raw is None:
        return None
    return datetime.fromisoformat(raw.replace("Z", "+00:00"))


def import_board(run, board_json):
    project = Project.objects.create(workspace=run.workspace, name=board_json["name"])
    for card in board_json["cards"]:
        try:
            Task.objects.create(project=project, title=card["name"], due=parse_due(card["due"]),
                                external_id=card["id"], source="trello")
        except ValueError as exc:
            run.errors.append(f"card {card['id']}: {exc}")
    run.cursor = board_json["id"]
    run.save()

