def start_impersonation(agent, target_user, ticket_id, write_mode=False):
    if write_mode and not ticket_id:
        raise PermissionDenied("write mode needs a ticket id")
    expires = now() + timedelta(minutes=30 if write_mode else 240)
    AuditEvent.objects.create(actor=agent, action="impersonate", target=target_user, ticket=ticket_id)
    return Session.objects.create(user=target_user, read_only=not write_mode, expires=expires)

