import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiFetch } from "../api/client";

export function Board({ projectId, columns }) {
  const qc = useQueryClient();
  const move = useMutation({
    mutationFn: (m) => apiFetch(`/tasks/${m.id}/move`, { method: "POST", body: m }),
    onError: () => qc.invalidateQueries(["board", projectId]),
  });
  const onDragEnd = (result) => move.mutate({ id: result.draggableId, before: result.beforeId });
  return <DragLayer columns={columns} onDragEnd={onDragEnd} />;
}

