export async function apiFetch(path: string, init: RequestInit = {}) {
  const csrf = document.cookie.match(/csrftoken=([^;]+)/)?.[1] ?? "";
  const res = await fetch(`/api/v1${path}`, { ...init, headers: { "X-CSRFToken": csrf } });
  if (!res.ok) throw new ApiError((await res.json()).error);
  return res.json();
}

export const searchTasks = debounce((q: string) => apiFetch(`/search?q=${encodeURIComponent(q)}`), 250);

